10	/**
11	 * Emits an audit line on successful owner creation via the dedicated {@code AUDIT}
12	 * logger, carrying the owner id, the {@code customerCode}, the
13	 * {@code registrationDate}, the {@code membershipLevel} and the
14	 * {@code membershipNumber}.
15	 *
16	 * <p>Runs after {@code SaveOwner} so the owner id has been assigned.
17	 */
18	public class AuditOwnerCreated {
19	
20	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
21	
22	    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
23	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
24	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
25	                ownerMapper.toMembershipLevel(owner), ownerMapper.toMembershipNumber(owner));
26	    }
27	}
