1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Derives an owner's {@code customerCode} — the owner's region-and-hash identity,
8	 * formatted {@code <REGION>-<HASH8>}:
9	 *
10	 * <ul>
11	 * <li>{@code REGION} is the region code derived from the postcode: look the postcode up
12	 * against the inclusive region ranges (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and,
13	 * only when the postcode is absent or in no known range, fall back to the fixed
14	 * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), else
15	 * {@code UNKNOWN}.</li>
16	 * <li>{@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
17	 * {@code normalizedTelephone + lastName}, where the telephone is normalized to E.164 form
18	 * (an absent or unparseable telephone contributes an empty string).</li>
19	 * </ul>
20	 *
21	 * <p>The whole owner identity — the {@code customerCode} itself, the values built from it
22	 * (membership number and its Luhn check digit), the create audit record and the derived
23	 * locality — flows from this single value. There is no sequence number.
24	 *
25	 * <p>A plain utility (not an OfficeFloor function), so it may expose helpers without
26	 * tripping the one-public-method-per-function rule.
27	 */
28	public final class OwnerCustomerCode {
29	
30	    /** City -> canonical region, matching the fixed table used to validate postcodes. */
31	    private static final Map<String, String> CITY_REGION = Map.of(
32	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
33	
34	    /** Region -> inclusive 4-digit postcode range {low, high}. */
35	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
36	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
37	
38	    private OwnerCustomerCode() {
39	    }
40	
41	    /** The full {@code <REGION>-<HASH8>} customer code for the given owner fields. */
42	    public static String of(String postcode, String city, String telephone, String lastName) {
43	        return region(postcode, city) + "-" + hash8(telephone, lastName);
44	    }
45	
46	    /**
47	     * The region code derived from the postcode (range lookup), falling back to the fixed
48	     * city-to-region table when the postcode is absent or in no known range, else
49	     * {@code UNKNOWN}.
50	     */
51	    public static String region(String postcode, String city) {
52	        if (postcode != null) {
53	            try {
54	                int value = Integer.parseInt(postcode.trim());
55	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
56	                    int[] range = entry.getValue();
57	                    if (value >= range[0] && value <= range[1]) {
58	                        return entry.getKey();
59	                    }
60	                }
61	            }
62	            catch (NumberFormatException ex) {
63	                // not a numeric postcode; fall back to the city table
64	            }
65	        }
66	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
67	    }
68	
69	    /**
70	     * The region for a city by the fixed city-to-region table
71	     * ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}), or {@code null} when the city has
72	     * no known region. Unlike {@link #region}, this does not fall back to {@code UNKNOWN}; it
73	     * exposes the raw city table so callers such as {@code ValidatePostcode} share this one
74	     * source of the region reference data.
75	     */
76	    public static String regionForCity(String city) {
77	        return CITY_REGION.get(city);
78	    }
79	
80	    /**
81	     * The inclusive 4-digit postcode range {@code {low, high}} pinned for a region (NSW
82	     * 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no pinned
83	     * range. The returned array is a copy, so callers cannot mutate the shared table.
84	     */
85	    public static int[] postcodeRange(String region) {
86	        int[] range = REGION_POSTCODES.get(region);
87	        return range == null ? null : range.clone();
88	    }
89	
90	    /**
91	     * The first 8 upper-case hex characters of SHA-256 over {@code normalizedTelephone +
92	     * lastName}, where the telephone is normalized to E.164 (an absent or unparseable
93	     * telephone, or an absent last name, contributes an empty string).
94	     */
95	    public static String hash8(String telephone, String lastName) {
96	        String tel = E164Telephone.normalizeOrNull(telephone);
97	        String normalizedTelephone = tel == null ? "" : tel;
98	        String last = lastName == null ? "" : lastName;
99	        return Sha256.hex(normalizedTelephone + last).substring(0, 8).toUpperCase(Locale.ROOT);
100	    }
101	}
