1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.mapper.OwnerMapper;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Assigns the owner's {@code membershipLevel}: the level derived from its membership points
10	 * (see {@link OwnerMapper#deriveMembershipLevel(Owner)}), but <em>capped</em> so it can never
11	 * exceed one above the current maximum membership level among the owner's existing household
12	 * members (owners sharing the same non-null {@code householdId}, excluding soft-deleted ones).
13	 * With no existing household member — a lone household, or an owner not in a shared household —
14	 * no cap applies and the derived level stands.
15	 *
16	 * <p>Runs after {@link AssignHouseholdSize} (so {@code householdId} and {@code householdSize},
17	 * which feeds the point total, are settled) but before {@link SaveOwner} (so the owner being
18	 * created is not yet persisted and cannot cap itself), mutating the owner in place so the
19	 * persisted value — and every later read — carries the capped level.
20	 */
21	public class AssignMembershipLevel {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository, OwnerMapper ownerMapper) {
24	        int level = ownerMapper.deriveMembershipLevel(owner);
25	        String householdId = owner.getHouseholdId();
26	        if (householdId != null) {
27	            Integer maxMemberLevel = null;
28	            for (Owner existing : ownerRepository.findAll()) {
29	                if (owner.getId() != null && owner.getId().equals(existing.getId())) {
30	                    continue; // never cap against itself
31	                }
32	                if (existing.isDeleted()) {
33	                    continue; // a soft-deleted owner no longer counts toward the household
34	                }
35	                if (!householdId.equals(existing.getHouseholdId())) {
36	                    continue;
37	                }
38	                int memberLevel = ownerMapper.toMembershipLevel(existing);
39	                if (maxMemberLevel == null || memberLevel > maxMemberLevel) {
40	                    maxMemberLevel = memberLevel;
41	                }
42	            }
43	            if (maxMemberLevel != null) {
44	                level = Math.min(level, maxMemberLevel + 1);
45	            }
46	        }
47	        owner.setMembershipLevel(level);
48	    }
49	}
