52	    private String city;
53	
54	    @Column(name = "telephone")
55	    @NotEmpty
56	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
57	        message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
58	    private String telephone;
59	
60	    @Column(name = "email")
61	    private String email;
62	
63	    @Column(name = "postcode")
