1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(toSelfLink(owner))")
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(toSalutation(owner))")
24	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(toCheckDigit(owner))")
27	    @Mapping(target = "membershipPoints", expression = "java(toMembershipPoints(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(toMembershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
30	    @Mapping(target = "timezone", expression = "java(toTimezone(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
32	    @Mapping(target = "identityKey", expression = "java(toIdentityKey(owner))")
33	    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
34	    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
35	    @Mapping(target = "fiscalYear", expression = "java(toFiscalYear(owner))")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /**
39	     * Derives the owner's {@code selfLink}: the canonical API path {@code /api/owners/} followed by
40	     * the owner's id. Returns null when the owner has no id (e.g. before it has been persisted).
41	     */
42	    default String toSelfLink(Owner owner) {
43	        if (owner.getId() == null) {
44	            return null;
45	        }
46	        return "/api/owners/" + owner.getId();
47	    }
48	
49	    /**
50	     * Derives the owner's {@code fiscalYear}: the fiscal year of the business-day-adjusted
51	     * {@code registrationDate}, formatted {@code FY<YY>} (see
52	     * {@link org.springframework.samples.petclinic.rest.function.owner.FiscalYear}). Returns null
53	     * when no registration date is present (e.g. unmigrated seed data).
54	     */
55	    default String toFiscalYear(Owner owner) {
56	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
57	        if (registrationDate == null) {
58	            return null;
59	        }
60	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYear.label(registrationDate);
61	    }
62	
63	    /**
64	     * Derives the owner's {@code salutation}: the {@code title} followed by a single space and the
65	     * {@code lastName} when a title is present, or just the {@code lastName} when no title was
66	     * supplied.
67	     */
68	    default String toSalutation(Owner owner) {
69	        String title = owner.getTitle();
70	        if (title == null || title.isBlank()) {
71	            return owner.getLastName();
72	        }
73	        return title + " " + owner.getLastName();
74	    }
75	
76	    /**
77	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted
78	     * for humans (see {@link org.springframework.samples.petclinic.rest.function.owner.E164Telephone#display}).
79	     * The raw {@code telephone} is left in E.164 form.
80	     */
81	    default String toTelephoneDisplay(Owner owner) {
82	        return org.springframework.samples.petclinic.rest.function.owner.E164Telephone
83	                .display(owner.getTelephone());
84	    }
85	
86	    /**
